#!/usr/bin/env node

import { readFile, writeFile } from "node:fs/promises";
import { resolve } from "node:path";

const root = process.cwd();
const wranglerPath = resolve(root, "worker/wrangler.jsonc");
const kotlinPath = resolve(
  root,
  "shared/src/commonMain/kotlin/com/kanarek/data/DefaultFeeds.kt",
);
const checkOnly = process.argv.includes("--check");

const wrangler = await readFile(wranglerPath, "utf8");
const match = wrangler.match(/"DEFAULT_FEEDS"\s*:\s*("(?:\\.|[^"\\])*")/);
if (!match) {
  throw new Error("worker/wrangler.jsonc does not define vars.DEFAULT_FEEDS");
}

const feeds = JSON.parse(match[1])
  .split(",")
  .map((feed) => feed.trim())
  .filter(Boolean);

if (feeds.length === 0) {
  throw new Error("vars.DEFAULT_FEEDS must contain at least one feed");
}
if (new Set(feeds).size !== feeds.length) {
  throw new Error("vars.DEFAULT_FEEDS contains duplicate URLs");
}
for (const feed of feeds) {
  const url = new URL(feed);
  if (url.protocol !== "http:" && url.protocol !== "https:") {
    throw new Error(`Default feed must use HTTP(S): ${feed}`);
  }
}

const kotlinString = (value) =>
  `"${value.replaceAll("\\", "\\\\").replaceAll('"', '\\"').replaceAll("$", "\\$")}"`;

const generated = `package com.kanarek.data

// Generated by .github/scripts/sync-default-feeds.mjs from worker/wrangler.jsonc.
// Edit vars.DEFAULT_FEEDS there, then run: node .github/scripts/sync-default-feeds.mjs
object DefaultFeeds {
    val urls: List<String> =
        listOf(
${feeds.map((feed) => `            ${kotlinString(feed)},`).join("\n")}
        )
}
`;

if (checkOnly) {
  const current = await readFile(kotlinPath, "utf8").catch(() => "");
  if (current !== generated) {
    console.error(
      "DefaultFeeds.kt is out of sync with worker/wrangler.jsonc. " +
        "Run: node .github/scripts/sync-default-feeds.mjs",
    );
    process.exitCode = 1;
  } else {
    console.log("Default feeds are in sync.");
  }
} else {
  await writeFile(kotlinPath, generated);
  console.log(`Generated ${feeds.length} default feeds.`);
}
